'hr.leave_import_hint' => 'Завантажте Excel із попередніми запитами на відпустку (аркуш «Leaves»: Email, Ім\'я латиницею, Ім\'я грецькою, Код типу, З, По, Дні, Години, Статус approved / rejected / pending, Причина, Action). Осіб зіставляють за e-mail облікового запису порталу, потім за грецьким або латинським ім\'ям; типи — за кодом. Рядки, що вже є в порталі (та сама особа, тип і дата початку), скасування та рядки з позначкою skip пропускаються. Затверджені рядки записуються як запити, затверджені HR, і потрапляють на дошку Планування; рядки в очікуванні чекають у запитах HR. Не рахуйте двічі: якщо імпорт балансів уже записав використані дні того ж року як початкові, обнуліть це значення для осіб, чиї відпустки ви імпортуєте тут.',
