'hr.ecd_training_auto' => 'обчислюється з навчань, відвіданих цього року (кількість і години), у рейтингу серед колег: перші 20 % = 5, наступні 20 % = 4, наступні 30 % = 3, решта = 2, жодного = 1.',
'hr.ecd_attendance_auto' => 'обчислюється за рік: починається з 5; −1 за кожні 16 год ранніх виходів / запізнень, −1 за кожні 3 дні незапланованої відсутності (без оплати, інша відсутність — лікарняний показується, але не штрафується), −1 за кожні 3 запити на відпустку, подані менш ніж за 2 дні. In / Out: сталість (дні з повними In та Out ÷ очікувані робочі дні, без схвалених відпусток) нижче 90 % коштує −1 за кожні розпочаті десять відсоткових пунктів, щонайбільше −3; не оцінюється до 20 очікуваних днів.',
'hr.ecd_targets' => 'цілі, задані для вас і вашого відділу, з їхнім прогресом і досягненням наприкінці року.',
'hr.ev_how_title' => 'Як ми вас оцінюємо',
'hr.ev_how_lede' => 'Щороку ваш керівник і HR оцінюють вашу роботу за вісьмома критеріями з балами від 1 до 5, плюс два бали, які портал обчислює з фактів року, і цілі, погоджені з вами. Остаточне оцінювання показується тут; ви коментуєте й підтверджуєте його.',
'hr.ev_how_criteria' => 'Вісім критеріїв',
'hr.ev_how_auto' => 'Обчислює портал',
'hr.ev_how_mine' => 'Ваші обчислені бали наразі за {y}',
'hr.ev_how_calendar' => 'Керівники пишуть чернетки в листопаді, HR переглядає в грудні, остаточні версії та підтвердження до 31 січня.',
'hr.ev_policy_hint' => 'Нотатка HR / керівництва, яку бачить кожен працівник під «Як ми вас оцінюємо» у Мої відпустки — чого компанія очікує цього року, як працюють приз і рейтинг, усе, що має знати персонал.',
