// ---- GAS-CP-R64-002 · assistant on evaluations and targets
'hr.ev_ai_title' => 'Асистент — чернетка та запитання',
'hr.ev_ai_hint' => 'Чернетка заповнює бали й тексти з фактів року (навчання, обчислені бали, цілі, попереднє оцінювання, активність у порталі, kudos) — перевірте кожен рядок перед збереженням. Запитати відповідає на запитання про рік людини. Персональні та зарплатні дані ніколи не надсилаються.',
'hr.ev_ai_ph' => 'Необов\'язкові вказівки: акцент на пусконалагодженні · суворість щодо надійності · три цілі з програмування PLC …',
