'hr.ev_ai_prefilled' => 'Чернетка асистента у формі; нічого не збережено, доки ви не натиснете Зберегти.',
'hr.ev_ai_discard' => 'Відхилити чернетку',
'hr.tg_ai_title' => 'Асистент — запропонувати цілі',
'hr.tg_ai_hint' => 'Пропонує 4–6 SMART-цілей на рік для відділу (люди та ролі) або людини (навчання, обчислені бали, останнє оцінювання, торішні цілі й результати). Додайте кожну одним кліком або спершу відредагуйте; нічого не створюється, доки ви її не додасте.',
'hr.tg_ai_go' => 'Запропонувати',
'hr.tg_ai_brief' => 'Вказівки (необов\'язково)',
'hr.tg_ai_ph' => 'напр. акцент на часі реакції сервісу та сертифікатах · узгодити з проєктами Lürssen 2027 …',
'hr.tg_ai_proposals' => '{n} пропозицій — додати або відредагувати',
'hr.tg_ai_add' => 'Додати',
'hr.imp_personal_skip' => 'Файл містить стовпці персональних / зарплатних даних, але ваш обліковий запис не HR і не Owner: ці стовпці буде проігноровано, а решту кожного рядка імпортовано. Увійдіть з обліковим записом HR або Owner, щоб їх імпортувати.',
