'hra.welcome_title' => 'Вітаємо, {n}',
'hra.welcome_1' => 'Цей асистент збирає дані вашої картки працівника за шість коротких кроків. Кожне поле попередньо заповнене тим, що HR має сьогодні: підтвердьте, виправте або залиште. Ви можете зупинитися будь-коли й продовжити пізніше — також із телефона.',
'hra.privacy_title' => 'Як ми обробляємо ваші дані',
'hra.privacy_1' => 'Контролер: Golden Automation Systems (Sistimata Ischyos ATEE), Kiou 5, Keratsini — для італійської філії GOLDEN AS ITALIAN. Мета: ведення особової справи, якої вимагає трудове, соціальне та податкове законодавство, і зв\'язок із вами або вашою контактною особою. Правова підстава: трудовий договір і законні обов\'язки роботодавця.',
'hra.privacy_2' => 'Введене тут зберігається у тимчасовій області до затвердження HR; ідентифікаційні номери (AMKA, податковий номер, ID, паспорт, IBAN) там зашифровані й доступні лише HR. Одержувачі: HR, Owner та, для нарахування зарплати, бухгалтер компанії. Зберігання: тимчасові дані видаляються через 90 днів після рішення; картка зберігається відповідно до строків особової справи.',
'hra.privacy_3' => 'Ваші права: доступ, виправлення (через цього асистента), видалення та обмеження, де це дозволяє закон, і скарга до Грецького органу захисту даних (dpa.gr). Запитання: HR › Повідомлення з HR.',
