'et.d_s_rfq' => "Запит пропозиції {no} — {branch}",
'et.d_b_rfq' => "Шановні панове,\n\nнадсилаємо {doc}. Просимо вказати найкращу ціну, термін постачання, строк дії та умови оплати по кожному рядку, із зазначенням виробника, типу та країни походження, і повернути пропозицію до дати, вказаної в документі, з посиланням на наш номер.\n\nЗ повагою,\n{user}\n{branch}",
'et.d_s_po_chase' => "Замовлення {no} — стан постачання",
'et.d_b_po_chase' => "Шановні панове,\n\nщодо {doc} просимо підтвердити стан нашого замовлення: готовий до відправки товар, дату відправки, перевізника та номер відстеження, а також позиції, що залишилися, з очікуваною датою.\n\nПостачання пов'язане з графіком судна; просимо негайно повідомляти про будь-яку затримку.\n\nЗ повагою,\n{user}\n{branch}",
'et.d_s_ncr' => "Невідповідність за замовленням {no}",
'et.d_b_ncr' => "Шановні панове,\n\nпід час приймання товару за {doc} ми зафіксували невідповідності, описані у доданому звіті (кількість, пошкодження або відхилення від замовлення). Просимо впродовж трьох робочих днів підтвердити спосіб урегулювання — заміна, кредит-нота чи ремонт — та дату.\n\nНевідповідні позиції зберігаються на нашому складі у вашому розпорядженні.\n\nЗ повагою,\n{user}\n{branch}",
'et.d_s_remittance' => "Повідомлення про оплату — {branch}",
'et.d_s_sup_statement' => "Statement of account — {branch}",
'et.d_b_remittance' => "Шановні панове,\n\nнадсилаємо повідомлення про оплату за {doc}. Суму переказано на рахунок, зазначений у вашому рахунку; просимо зарахувати її на перелічені рахунки та надіслати нам підтвердження.\n\nЗ повагою,\n{user}\n{branch}",
'et.d_b_sup_statement' => "Dear Sir / Madam,\n\nPlease find attached the {doc} as it stands in our books. Kindly check it against your records and let us know of any difference.\n\nBest regards,\n{user}\n{branch}",
