'et.d_s_rc_general' => "Ваша заявка {no} — {title} — Golden A/S",
'et.d_s_rc_shortlisted' => "Ваша заявка на посаду {title} — наступний крок — Golden A/S",
'et.d_s_rc_interview' => "Запрошення на співбесіду — {title} — Golden A/S",
'et.d_s_rc_offer' => "Пропозиція — {title} — Golden A/S",
'et.d_s_rc_rejected' => "Ваша заявка на посаду {title} — Golden A/S",
'et.d_b_rc_general' => "Шановний/а {name},\n\nДякуємо за Вашу заявку {no} на посаду {title} ({doc}).\n\n\n\nЗ повагою,\n{user}\n{branch}",
'et.d_b_rc_shortlisted' => "Шановний/а {name},\n\nДякуємо за Вашу заявку на посаду {title}. Ми розглянули її з інтересом і хотіли б запросити Вас на наступний етап відбору.\n\nНезабаром ми зв'яжемося з Вами, щоб узгодити зручний час. Тим часом повідомте нас, якщо зміниться Ваша доступність.\n\nЗ повагою,\n{user}\n{branch}",
'et.d_b_rc_interview' => "Шановний/а {name},\n\nУ зв'язку з Вашою заявкою на посаду {title} ми хотіли б запросити Вас на співбесіду.\n\nДата і час: {when}\nТривалість: {duration}\nФормат / місце: {mode}\nУчасники: {interviewers}\n\nБудь ласка, підтвердьте, що запропонований час Вам підходить, або запропонуйте інший.\n\n{signature}",
'et.d_b_rc_offer' => "Шановний/а {name},\n\nРаді повідомити, що за результатами відбору ми хотіли б запропонувати Вам посаду {title}.\n\nНаша пропозиція:\n\nЧиста заробітна плата: {salary}\nДоговір: {contract}\nДата початку: {start}\nРобочий час: {hours}\nМісце роботи: {place}\nВипробувальний термін: {probation}\nПільги: {benefits}\nІнші умови: {terms}\nПропозиція дійсна до: {valid}\n\nВи отримаєте окремий лист від Golden A/S з особистим посиланням, де приймаєте пропозицію та дату початку. Якщо бажаєте спершу обговорити якийсь пункт, дайте відповідь на цей лист. Чекаємо на Вас у команді.\n\nПосадова інструкція\n----------------------------------------\n{jd}\n\n{signature}",
'et.d_b_rc_rejected' => "Шановний/а {name},\n\nДякуємо за Вашу заявку на посаду {title} і за час, який Ви присвятили нашому процесу відбору.\n\nПісля ретельного розгляду ми вирішили продовжити з іншими кандидатами, чий профіль ближчий до вимог цієї ролі. Ми збережемо Ваші дані протягом шести місяців і зв'яжемося з Вами, якщо відкриється відповідна вакансія.\n\nБажаємо Вам успіхів.\n\nЗ повагою,\n{user}\n{branch}",
'rc.key_once_hint' => 'Скопіюйте його зараз у secret PORTAL_RC_KEY (або PORTAL_STATS_KEY) репозиторію сайту — під час наступного завантаження він замаскований.',
