'io.stats_foot' => 'Сталість = робочі дні з повним Входом і Виходом до робочих днів періоду. Точність = відмітки без винятку. Вчасно = перший Вхід дня в межах допуску. Схвалена відпустка ще не віднімається від робочих днів.',
