'io.st_ot' => 'Схвалені понаднормові',
'io.c_title' => 'Вхід / Вихід — запис часу та місця',
'io.c_text' => "Golden A/S записує час і місце вашого телефона в момент, коли ви відмічаєте вхід, і в момент, коли відмічаєте вихід, разом із найближчим об'єктом компанії, точністю місця та використаним застосунком чи комп'ютером. Між цими моментами ваше місце не відстежується.\n\nДані використовуються для підтвердження присутності на місці роботи, робочого часу та понаднормових. Вони порівнюються з вашим табелем і сервісними звітами та враховуються в оцінюванні персоналу (сталість і точність).\n\nВаші записи бачать HR, керівництво, ваш керівник і керівники проєктів; статистику — лише HR, CEO та генеральний менеджер. Власні записи ви бачите в застосунку й на порталі.\n\nПолітика конфіденційності: https://www.goldenas.com.gr/privacy.html",
'io.c_accept' => 'Я прочитав(ла) це повідомлення і приймаю запис часу та місця мого входу / виходу.',
'io.c_btn' => 'Прийняти й продовжити',
