'io.fl_steps' => 'Кроки словами',
'io.fl_p1' => 'Повідомлення. Коли ви вперше користуєтеся In / Out, ви читаєте повідомлення про запис часу та позиції і приймаєте його — один раз, у застосунку або на порталі. Прийняття записується у ваш журнал HR. Без нього жоден запис не реєструється.',
'io.fl_p2' => 'In. Коли ви починаєте роботу, натискаєте In. Застосунок записує час, позицію телефона в цей момент і найближчий об\'єкт компанії. На порталі In / Out працює лише із зареєстрованої мережевої адреси об\'єкта компанії. Ваша позиція не відстежується між In та Out.',
'io.fl_p3' => 'Автоматична перевірка. Кожен запис перевіряється одразу: чи він у межах відомого об\'єкта, у робочий час (до {t} хвилин після початку ще вважається вчасним) і чи надійна позиція. Запис без зауважень приймається автоматично. Запис із зауваженням — поза об\'єктом, запізнення, раніше, слабка або відсутня позиція, Out без In, подвійний запис — є винятком: він чекає в «На рішення», доки ваш керівник, менеджер проєкту або HR схвалить чи відхилить його з приміткою.',
'io.fl_p4' => 'Out. Коли ви закінчуєте роботу, натискаєте Out. Він проходить ту саму перевірку, що й In. Дозволено кілька пар In / Out за один день (наприклад, візит на судно і повернення до офісу).',
'io.fl_p5' => 'Результат дня. Портал додає час між кожним In та його Out. У робочий день від п\'яти годин віднімається перерва з вашого календаря робочого часу. Те, що перевищує заплановані години, є понаднормовим, якщо це щонайменше {o} хвилин; увесь час у неробочий день є понаднормовим.',
'io.fl_p6' => 'Перехресна перевірка. Чистий час дня порівнюється з годинами, які ви записали в timesheet, і з робочим часом (WT) у сервісних звітах за той самий день. Різниця понад {m} хвилин із timesheet у будь-який бік або більше робочого часу в сервісних звітах, ніж показує присутність, позначається в «Понаднормові та звірка», щоб виправити timesheet, звіт або запис.',
'io.fl_p7' => 'Рішення щодо понаднормових. Понаднормові не приймаються самі собою. Особа, яка вирішує щодо ваших записів, схвалює або відхиляє їх за днями, з приміткою. Відхилені записи не враховуються в результаті дня.',
'io.fl_p8' => 'Статистика. Для кожної особи HR, генеральний директор і головний менеджер бачать три показники за період: сталість (робочі дні з повними In та Out), точність (записи без зауважень) і вчасність (перший In дня в межах допуску).',
'io.fl_p9' => 'Оцінювання персоналу. Сталість за рік є частиною обчисленої оцінки «Присутність і послідовність» річного оцінювання; точність і частка вчасних приходів показуються поруч, оцінювачу та вам у My HR.',
'io.fl_ev_h' => 'Зв\'язок з оцінюванням персоналу',
'io.fl_ev_p1' => 'Річне оцінювання має два критерії, які обчислює портал. «Присутність і послідовність» починається з 5 і втрачає бали за ранні виходи та запізнення, незаплановані відсутності та відпустки, запитані в останню мить (зі схвалених заявок HR за рік), і за сталість In / Out.',
'io.fl_ev_p2' => 'Сталість In / Out = дні з повними In та Out ÷ очікувані дні. Очікувані — це робочі дні вашого календаря від першого запису року до сьогодні; дні схваленої відпустки, лікарняного або відсутності без запису не враховуються. Від 90 % нічого не відраховується; нижче — один бал за кожні розпочаті десять відсоткових пунктів (80–89 %: −1, 70–79 %: −2, нижче: −3). Якщо очікуваних днів менше ніж 20, показник показується і ще не оцінюється. Відсоток першого порога задається в Об\'єкти та правила.',
'io.fl_ev_p3' => 'Точність і частка вчасних приходів показуються під критерієм і не змінюють оцінку. Свої показники ви бачите в My HR › Як ми вас оцінюємо.',
'io.ev_txt' => 'In / Out за рік: сталість {c} ({d} із {w} очікуваних днів; {x} день/днів схваленої відпустки або відсутності не враховано) · точність {a} · вчасність {p} — {s}',
'ft.title' => 'Кошик',
'ft.lede' => 'Файли, вилучені користувачами, зберігаються тут {d} днів. До того часу адміністратор може відновити файл на місце, звідки він походить, або вилучити його остаточно. Через {d} днів портал вилучає його остаточно сам.',
