'ft.rule_2' => 'Файл може вилучити той, хто його завантажив, менеджер проєкту цього проєкту та адміністратори.',
'ft.rule_3' => 'Видані документи, надіслані пропозиції та їхні вкладення, підписані сервісні та інспекційні звіти і рахунки постачальників захищені: їх вилучає лише адміністратор, із письмовою причиною.',
'ft.rule_4' => 'Відновлений файл повертається зі своїм старим номером, тож кожен запис, який на нього вказував, знову працює. Файл не відновлюється, якщо проєкт, пропозицію або тікет, до якого він належав, видалено.',
