'pdc.xl_tpl' => 'Шаблон Excel',
'pdc.xl_lede' => 'Excel: коли рядки документа є у вигляді списку, заповніть шаблон (Code і Qty обов язкові) і завантажте його замість скану. Рядки беруться точно так, як введені, і зіставляються із замовленням за кодом — наш код, код виробника або код, запам ятований для цього постачальника. Лише рядки з кодом, якого немає в замовленні, передаються асистенту.',
'pdc.xl_only' => 'Файл Excel у форматі шаблону можна перевірити й без асистента: він зіставляється за кодом.',
'pdc.xl_hint' => 'Excel (.xlsx) у форматі шаблону, до 2 МБ і 300 рядків. Один документ на перевірку.',
