'pdc.xl_skipped' => '{n} рядків без кількості більше нуля пропущено.',
'pdc.xl_no_ask' => 'Рядки поза замовленням не передано асистенту (вимкнений, ліміт вичерпано або немає відповіді) — перевірте їх вручну.',
'pdc.xl_reading_h' => 'Файл порівнюється із замовленням',
'pdc.xl_reading' => 'Рядки файлу зіставляються із замовленням за кодом. Це триває кілька секунд; довше лише тоді, коли рядки поза замовленням передаються асистенту. Сторінка оновлюється сама.',
'pdc.xl_tpl_title' => 'Документ поставки в Excel — як заповнити',
'pdc.xl_tpl_n0' => 'Для замовлення на закупівлю {po}. Один рядок на кожен рядок документа постачальника, на першому аркуші, заголовки в рядку 1. Завантажте його в замовленні › Перевірка поставки.',
'pdc.xl_tpl_n1' => 'Code (обов язково): код, як надруковано в документі. Порівнюється з нашим кодом, кодом виробника рядка замовлення та кодами, запам ятованими для цього постачальника; великі літери, пробіли, крапки й дефіси не мають значення.',
'pdc.xl_tpl_n2' => 'Qty (обов язково): поставлена кількість, більше нуля. Рядки без неї пропускаються й підраховуються.',
'pdc.xl_tpl_n3' => 'Description і Unit: як надруковано. Використовуються, коли треба створити нову складську позицію або новий рядок замовлення.',
'pdc.xl_tpl_n4' => 'Ціни (можуть лишатися порожніми): Unit price і Discount % документа, або Net unit price, або Net value рядка. Зберігається чиста ціна за одиницю: Net unit price, інакше Unit price мінус знижка, інакше Net value ÷ Qty.',
'pdc.xl_tpl_n5' => 'Document No, Document date (дд/мм/рррр) і Document type (invoice або delivery note): діє перший заповнений рядок. PO No: якщо заповнено, має бути {po} — файл іншого замовлення відхиляється.',
'pdc.xl_tpl_n6' => 'PO line (необов язково): номер рядка замовлення, до якого належить рядок. Використовуйте, коли той самий код є в кількох рядках, або для компонентів, поставлених замість вузла (кілька рядків з тим самим рядком замовлення).',
'pdc.xl_tpl_n7' => 'До {max} рядків і 2 МБ. Без формул, підсумків чи об єднаних клітинок; той самий код може бути в кількох рядках. Приймаються також грецькі заголовки документа: Κωδικός, Περιγραφή, Ποσότητα, Μ.Μ., Τιμή, Εκπτ.%, Καθαρή αξία.',
